from pathlib import Path
import pandas as pd
import openpyxl
from docx import Document

ROOT = Path('/root')
manifest_path = ROOT / 'Manifest_Plan.xlsx'
template_path = ROOT / 'Outbound_Audit_Template.xlsx'
out_xlsx = ROOT / 'Outbound_Load_Audit.xlsx'
out_docx = ROOT / 'Outbound_Load_Brief.docx'
formatted_headers = [
    'Shipment ID', 'Carton ID', 'Planned Zone', 'Route', 'Expected Weight',
    'Hazmat Flag', 'Carrier', 'Wave', 'Missing Load Scan', 'Zone Mismatch',
    'Total Errors', 'Error Summary'
]
summary_headers = ['Route', 'Shipment ID', 'Missing Load Scans', 'Zone Mismatches', 'Total Errors']

errors=[]

def fail(msg):
    errors.append(msg)

# Workbook/sheet validation
wb_out = openpyxl.load_workbook(out_xlsx, data_only=True)
wb_tmpl = openpyxl.load_workbook(template_path, data_only=True)
expected_sheets = ['Overview','RawData','Formatted Data','Summary']
for s in expected_sheets:
    if s not in wb_out.sheetnames:
        fail(f'missing sheet {s}')

# Overview unchanged: compare dimensions and all cell values over union dimensions.
ws_o = wb_out['Overview']; ws_t = wb_tmpl['Overview']
max_row=max(ws_o.max_row, ws_t.max_row); max_col=max(ws_o.max_column, ws_t.max_column)
for r in range(1,max_row+1):
    for c in range(1,max_col+1):
        if ws_o.cell(r,c).value != ws_t.cell(r,c).value:
            fail(f'Overview changed at {r},{c}: {ws_o.cell(r,c).value!r} != {ws_t.cell(r,c).value!r}')
            break

manifest = pd.read_excel(manifest_path, engine='openpyxl')
raw = pd.read_excel(out_xlsx, sheet_name='RawData', engine='openpyxl')
formatted = pd.read_excel(out_xlsx, sheet_name='Formatted Data', engine='openpyxl')
summary = pd.read_excel(out_xlsx, sheet_name='Summary', engine='openpyxl')

if list(raw.columns) != list(manifest.columns):
    fail(f'RawData columns differ: {list(raw.columns)} vs {list(manifest.columns)}')
if len(raw) != len(manifest):
    fail(f'RawData row count {len(raw)} != manifest {len(manifest)}')
if not raw.equals(manifest):
    fail('RawData values/order differ from manifest')

if list(formatted.columns) != formatted_headers:
    fail(f'Formatted headers invalid: {list(formatted.columns)}')
if len(formatted.columns) != 12:
    fail(f'Formatted column count {len(formatted.columns)} != 12')
if len(formatted) != len(manifest):
    fail(f'Formatted row count {len(formatted)} != manifest {len(manifest)}')
if not formatted[formatted_headers[:8]].equals(raw[formatted_headers[:8]]):
    fail('Formatted first 8 columns/order do not match RawData')

# Sample/internal consistency checks for all rows, stronger than a few samples.
valid_summaries = {'None','Missing Load Scan','Zone Mismatch','Missing Load Scan, Zone Mismatch'}
for idx,row in formatted.iterrows():
    m=int(row['Missing Load Scan']); z=int(row['Zone Mismatch']); t=int(row['Total Errors'])
    parts=[]
    if m: parts.append('Missing Load Scan')
    if z: parts.append('Zone Mismatch')
    expected=', '.join(parts) if parts else 'None'
    if m not in (0,1) or z not in (0,1):
        fail(f'row {idx} non-binary flags')
    if t != m+z:
        fail(f'row {idx} Total Errors inconsistent')
    if row['Error Summary'] not in valid_summaries or row['Error Summary'] != expected:
        fail(f'row {idx} Error Summary inconsistent: {row["Error Summary"]!r}, expected {expected!r}')

if list(summary.columns) != summary_headers:
    fail(f'Summary headers invalid: {list(summary.columns)}')
if len(summary) == 0 or summary.iloc[-1]['Route'] != 'Grand Total' or str(summary.iloc[-1]['Shipment ID']) != '-':
    fail('Grand Total row missing/not last')
summary_detail = summary.iloc[:-1].copy()
if (summary_detail['Total Errors'] <= 0).any():
    fail('Summary detail contains Total Errors <= 0')
if not summary_detail[['Route','Shipment ID']].reset_index(drop=True).equals(summary_detail.sort_values(['Route','Shipment ID'], kind='mergesort')[['Route','Shipment ID']].reset_index(drop=True)):
    fail('Summary detail not sorted by Route then Shipment ID')

formatted_totals = {
    'Missing Load Scans': int(formatted['Missing Load Scan'].sum()),
    'Zone Mismatches': int(formatted['Zone Mismatch'].sum()),
    'Total Errors': int(formatted['Total Errors'].sum()),
}
grand = summary.iloc[-1]
for col,val in formatted_totals.items():
    if int(grand[col]) != val:
        fail(f'Grand Total {col} {grand[col]} != formatted total {val}')
    if int(summary_detail[col].sum()) != val:
        fail(f'Summary detail sum {col} {summary_detail[col].sum()} != formatted total {val}')

# Recompute top shipment IDs from Summary detail, ties by Shipment ID.
priority = (summary_detail.groupby('Shipment ID', as_index=False)['Total Errors'].sum()
            .sort_values(['Total Errors','Shipment ID'], ascending=[False, True], kind='mergesort'))
top_shipments = priority['Shipment ID'].head(2).tolist()

# Docx validation
text = '\n'.join(p.text for p in Document(out_docx).paragraphs)
required_phrases = [
    'Missing Load Scan means the carton has no LOADED dock scan recorded',
    'Zone Mismatch means the carton was loaded but scanned in a zone different from its planned zone',
    str(formatted_totals['Missing Load Scans']),
    str(formatted_totals['Zone Mismatches']),
    str(formatted_totals['Total Errors']),
]
for phrase in required_phrases:
    if phrase not in text:
        fail(f'docx missing phrase/number: {phrase}')
for sid in top_shipments:
    if sid not in text:
        fail(f'docx missing high-priority Shipment ID: {sid}')
if not any(word in text.lower() for word in ['recommend', 'retrain', 'audit scanner', 'review']):
    fail('docx appears to lack actionable recommendation')

if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
print('VALIDATION PASSED')
print('sheets:', wb_out.sheetnames)
print('row_counts:', {'RawData': len(raw), 'Formatted Data': len(formatted), 'Summary': len(summary)})
print('totals:', formatted_totals)
print('top_shipments:', top_shipments)
print('docx_text:', text)
print('sample_rows:', formatted.head(5).to_dict(orient='records'))

